// ---- Sediment-routing delta (DeltaRCM-lite) --------------------------------
// Parcels of sediment leave the trunk apex and walk the bed by weighted steepest
// descent. Subaerial -> the parcel incises a channel and picks up load.
// Subaqueous -> it settles exponentially, so a mouth bar builds AT the shoreline
// and forces the flow to bifurcate around it: distributaries are emergent, not
// drawn. Aggradation then superelevates the active lobe until a lower path wins
// and the flow AVULSES to a new one.
// Anti-convergence: relative sea level oscillates (transgression drowns the
// plain, regression progrades and incises it), the trunk apex wanders over
// minutes so lobes switch, and subsidence keeps making accommodation. The
// basin therefore never fills and the piece never reaches equilibrium.
const BW = 176, BH = 99, N = BW * BH;

const sd = P.seed | 0;
function hsh(ix, iy) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}
function vn(x, y) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = hsh(ix, iy), b = hsh(ix + 1, iy), c = hsh(ix, iy + 1), d2 = hsh(ix + 1, iy + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d2) * u * v;
