if (!S.g) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.Z = new Float32Array(N); S.T = new Float32Array(N); S.T2 = new Float32Array(N);
  S.seedUsed = null;
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  // antecedent margin: alluvial plain at the left, ramp down into a basin right
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const u = i / BW, v = j / BH;
    S.Z[j * BW + i] = 0.30 - u * 0.88 + (fbm(u * 5 + 1.3, v * 5 + 2.7) - 0.5) * 0.11 - Math.abs(v - 0.5) * 0.05;
    S.T[j * BW + i] = 0;
  }
  S.rng = (Math.imul(sd, 2654435761) + 12345) >>> 0;
