// ---- route sediment parcels ------------------------------------------------
const sub = S.warm > 0 ? 12 : 1;
const NP = Math.round((30 + P.density * 105) * (0.6 + disch * 0.6));
const L0 = 0.0045 * (0.5 + P.energy * 0.9);
for (let pass = 0; pass < sub; pass++) {
  for (let p = 0; p < NP; p++) {
    let x = 2.5, y = apexY + (rnd() - 0.5) * BH * 0.09;
    let dirx = 1, diry = 0, load = L0, wet = 0;
    // Step budget must outlast the widest the plain ever gets. At 90 the parcels
    // ran out of steps crossing a prograded plain and never reached the sea, which
    // silently killed the mouth bar and the plume.
    for (let s2 = 0; s2 < 320; s2++) {
      const xi = x | 0, yi = y | 0;
      if (xi < 1 || xi >= BW - 1 || yi < 1 || yi >= BH - 1) break;
      const k = yi * BW + xi;
      let bx = 0, by = 0, bw = -1e9;
      for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
        if (!a && !b) continue;
        const drop = S.Z[k] - S.Z[(yi + b) * BW + (xi + a)];
        const inert = (a * dirx + b * diry) * 0.42;
        const w = drop * 26 + inert + rnd() * 0.5;
        if (w > bw) { bw = w; bx = a; by = b; }
      }
      dirx = bx; diry = by;
      const depth = sl - S.Z[k];
      if (depth <= 0.002) {
        // Subaerial. Incise only where the bed is STEEP (that is a channel);
        // aggrade where it is flat (overbank / crevasse splay). Both conserve
        // mass into the parcel's load. Incising every subaerial step instead
        // grinds the whole plain away faster than the delta can build it.
        const drop = S.Z[k] - S.Z[(yi + by) * BW + (xi + bx)];
        if (drop > 0.004) {
          const e = 0.00075 * (0.4 + P.energy * 0.9) * (0.5 + disch * 0.8) * Math.min(1, drop * 55);
          S.Z[k] -= e; load += e;
        } else {
          // Overbank is a SMALL fraction — most of the load must survive the
          // plain and reach the mouth, or the bar never builds and the plume dies.
          const dp = load * 0.003; S.Z[k] += dp; load -= dp;
        }
      } else {
        wet++;
        const dep = load * 0.11;                     // exponential settling -> mouth bar -> bifurcation
        S.Z[k] += dep; load -= dep;
