        // visible density regardless of the absolute (tiny) elevation units
        S.T[k] += (load / L0) * 0.045;
        if (S.T[k] > 1.4) S.T[k] = 1.4;
        if (load < L0 * 0.04 || wet > 34) break;
      }
      x += bx; y += by;
    }
  }
  if (S.warm > 0) S.warm--;
}

// ---- subsidence + clamps (accommodation is created forever) ----------------
// Subsidence tapers to zero as the bed approaches the basin floor, so the margin
// has finite accommodation. Without this it outruns deposition and the whole
// frame slowly drowns into a flat dark field over ~10 minutes.
const subs = 0.000011 * spd;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  const k = j * BW + i;
  S.Z[k] -= subs * (0.35 + 0.65 * (i / BW)) * Math.max(0, S.Z[k] + 1.0);
  if (S.Z[k] < -1.15) S.Z[k] = -1.15; else if (S.Z[k] > 0.5) S.Z[k] = 0.5;
}
// diffuse + decay the plume (keeps it a cloud, not a speckle trail)
const Td = 0.92 - (1 - P.density) * 0.05;
for (let j = 1; j < BH - 1; j++) for (let i = 1; i < BW - 1; i++) {
  const k = j * BW + i;
  S.T2[k] = (S.T[k] * 0.52 + (S.T[k - 1] + S.T[k + 1] + S.T[k - BW] + S.T[k + BW]) * 0.12) * Td;
}
const tmp = S.T; S.T = S.T2; S.T2 = tmp;

// ---- render ----------------------------------------------------------------
const st = P.style;
const rot = h => (((h + (P.hue - 195)) % 360) + 360) % 360;
function hsv(h, s, v) {
  h = ((h % 360) + 360) % 360 / 60; const c = v * s, xx = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  let r, g2, b2;
  if (h < 1) { r = c; g2 = xx; b2 = 0; } else if (h < 2) { r = xx; g2 = c; b2 = 0; }
  else if (h < 3) { r = 0; g2 = c; b2 = xx; } else if (h < 4) { r = 0; g2 = xx; b2 = c; }
  else if (h < 5) { r = xx; g2 = 0; b2 = c; } else { r = c; g2 = 0; b2 = xx; }
