}
const gain = 0.72 + P.energy * 0.5 + K.intensity * 0.16 + A.rms * 0.3;
const laz = K.t * 0.043 + 1.1 + 0.3 * Math.sin(K.t * 0.017);   // light drifts: a motion floor on the land
const lx = Math.cos(laz), ly = Math.sin(laz);
const g = S.g; g.loadPixels(); const px = g.pixels;
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  const k = j * BW + i;
  const z = S.Z[k], depth = sl - z;
  const i0 = i > 0 ? i - 1 : 0, i1 = i < BW - 1 ? i + 1 : BW - 1;
  const j0 = j > 0 ? j - 1 : 0, j1 = j < BH - 1 ? j + 1 : BH - 1;
  const gx = (S.Z[j * BW + i1] - S.Z[j * BW + i0]) * 26, gy = (S.Z[j1 * BW + i] - S.Z[j0 * BW + i]) * 26;
